            // Draw Main Unit Body
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, globalTime, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, globalTime, isSilhouette);
