        ctx.scale(scaleFactor, scaleFactor);

        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;
        const physZ = agent.physics.z / scaleFactor; 

        // --- 1. SELECTION BRACKET (Draw BEFORE body rotation/float to stay stable) ---
        if (isSelected && !isSilhouette) {
            ctx.save();
            ctx.translate(physX, physY - physZ);
            ctx.translate(0, -45); // Center on chest height (approx)

            // Sci-Fi Rotating Bracket
            ctx.save();
            const bracketSize = 55; // Scaled units
            ctx.rotate(globalTime * 0.5);
            ctx.lineWidth = 3;
            ctx.strokeStyle = '#22d3ee'; 
            ctx.shadowColor = '#06b6d4';
            ctx.shadowBlur = 10;

            const cornerLen = Math.PI / 3;
            for(let i=0; i<4; i++) {
